<!--
 * 重试预览管理页面
 *
 * <p>展示消息重试计划和预设配置，支持查看重试调度详情。
 *
 * @path apps/message-web/src/views/retry-preview/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 重试预览管理（双 Tab 页）
 * <p>消费后端契约 RetryPreviewController（src/api/retryPreview.ts，auto-generated by bash/gen-contract.py）：
 * previewRetrySchedule() 查询重试计划列表，previewAllPresets() 查询所有预设，
 * listPresets() 查询预设配置列表。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { Page } from '@ydsz/common-ui';

import { createLogger } from '@ydsz-core/shared/utils';
import {
  ElButton,
  ElCard,
  ElDialog,
  ElEmpty,
  ElOption,
  ElSelect,
  ElTable,
  ElTableColumn,
  ElTabPane,
  ElTabs,
  ElTag,
} from 'element-plus';
import { onMounted, reactive, ref } from 'vue';

import { listPresets, previewAllPresets, previewRetrySchedule } from '#/api/retryPreview';

defineOptions({ name: 'RetryPreviewManagement' });

const logger = createLogger('retry-preview');

/** 当前激活的 Tab */
const activeTab = ref('retry-preview');

/** 重试计划列表 */
const retryScheduleList = ref<Record<string, unknown>[]>([]);

/** 重试计划加载状态 */
const scheduleLoading = ref(false);

/** 预设列表 */
const presetList = ref<Record<string, unknown>[]>([]);

/** 预设加载状态 */
const presetLoading = ref(false);

/** 预设查询参数 */
const searchParams = reactive({
  preset: '',
});

/** 重试计划详情弹窗可见性 */
const detailVisible = ref(false);

/** 当前查看详情的重试计划 */
const currentDetail = ref<Record<string, unknown> | null>(null);

/** 所有预设映射（用于下拉选择） */
const allPresets = ref<Record<string, Record<string, unknown>>>({});

/** 将 Map 转换为数组便于表格渲染 */
function mapToArray(map: Record<string, Record<string, unknown>>): Record<string, unknown>[] {
  return Object.entries(map).map(([key, value]) => ({
    key,
    ...value,
  }));
}

/** 加载重试计划列表 */
async function loadRetrySchedule(): Promise<void> {
  scheduleLoading.value = true;
  try {
    const res = await previewRetrySchedule({
      preset: searchParams.preset || undefined,
    });
    retryScheduleList.value = mapToArray(res ?? {});
  } catch (error) {
    logger.warn('查询重试计划失败: {}', error);
    retryScheduleList.value = [];
  } finally {
    scheduleLoading.value = false;
  }
}

/** 加载预设列表 */
async function loadPresets(): Promise<void> {
  presetLoading.value = true;
  try {
    const res = await listPresets();
    presetList.value = mapToArray(res ?? {});
  } catch (error) {
    logger.warn('查询预设列表失败: {}', error);
    presetList.value = [];
  } finally {
    presetLoading.value = false;
  }
}

/** 加载所有预设（用于下拉和初始化） */
async function loadAllPresets(): Promise<void> {
  try {
    const res = await previewAllPresets();
    allPresets.value = res ?? {};
  } catch (error) {
    logger.warn('查询所有预设失败: {}', error);
    allPresets.value = {};
  }
}

/** 执行查询 */
function handleSearch(): void {
  if (activeTab.value === 'retry-preview') {
    loadRetrySchedule();
  }
}

/** 查看重试计划详情 */
function handleViewDetail(row: Record<string, unknown>): void {
  currentDetail.value = row;
  detailVisible.value = true;
}

/** 重置查询 */
function handleReset(): void {
  searchParams.preset = '';
  handleSearch();
}

/** Tab 切换事件 */
function handleTabChange(tabName: string): void {
  logger.info('切换到 Tab: {}', tabName);
  if (tabName === 'retry-preview') {
    loadRetrySchedule();
  } else {
    loadPresets();
  }
}

onMounted(() => {
  loadAllPresets();
  loadRetrySchedule();
});
</script>

<template>
  <Page auto-content-height>
    <div class="retry-preview-container p-4">
      <!-- Tab 切换区 -->
      <ElCard class="mb-4" shadow="never">
        <ElTabs v-model="activeTab" @tab-change="handleTabChange">
          <ElTabPane label="重试预览" name="retry-preview" />
          <ElTabPane label="预设配置" name="presets" />
        </ElTabs>
      </ElCard>

      <!-- 重试预览 Tab -->
      <template v-if="activeTab === 'retry-preview'">
        <!-- 查询区域 -->
        <ElCard class="mb-4" shadow="never">
          <div class="flex items-center gap-3">
            <ElSelect v-model="searchParams.preset" placeholder="选择预设" class="w-48" clearable>
              <ElOption
                v-for="(val, key) in allPresets"
                :key="key"
                :label="String(key)"
                :value="String(key)"
              />
            </ElSelect>
            <ElButton type="primary" @click="handleSearch">查询</ElButton>
            <ElButton @click="handleReset">重置</ElButton>
          </div>
        </ElCard>

        <!-- 重试计划列表 -->
        <ElCard shadow="never">
          <ElTable
            v-loading="scheduleLoading"
            :data="retryScheduleList"
            stripe
            border
            style="width: 100%"
          >
            <ElTableColumn type="index" label="序号" width="60" align="center" />
            <ElTableColumn prop="key" label="消息/标识" width="200" show-overflow-tooltip />
            <ElTableColumn label="通道" width="120">
              <template #default="{ row }">
                <ElTag v-if="row.channel" size="small">{{ row.channel }}</ElTag>
                <span v-else>-</span>
              </template>
            </ElTableColumn>
            <ElTableColumn prop="failReason" label="失败原因" min-width="180" show-overflow-tooltip />
            <ElTableColumn label="重试次数" width="100" align="center">
              <template #default="{ row }">
                <span class="font-mono text-orange-600">{{ row.retryCount ?? '-' }}</span>
              </template>
            </ElTableColumn>
            <ElTableColumn label="下次重试时间" width="170">
              <template #default="{ row }">
                {{ row.nextRetryAt ?? '-' }}
              </template>
            </ElTableColumn>
            <ElTableColumn label="状态" width="100" align="center">
              <template #default="{ row }">
                <ElTag v-if="row.status" size="small">{{ row.status }}</ElTag>
                <span v-else>-</span>
              </template>
            </ElTableColumn>
            <ElTableColumn label="操作" width="120" fixed="right" align="center">
              <template #default="{ row }">
                <ElButton size="small" link type="primary" @click="handleViewDetail(row)">
                  查看详情
                </ElButton>
              </template>
            </ElTableColumn>
            <template #empty>
              <ElEmpty description="暂无重试计划数据" />
            </template>
          </ElTable>
        </ElCard>
      </template>

      <!-- 预设配置 Tab -->
      <template v-else>
        <!-- 预设列表 -->
        <ElCard shadow="never">
          <ElTable
            v-loading="presetLoading"
            :data="presetList"
            stripe
            border
            style="width: 100%"
          >
            <ElTableColumn type="index" label="序号" width="60" align="center" />
            <ElTableColumn prop="key" label="预设标识" width="200" show-overflow-tooltip />
            <ElTableColumn prop="name" label="预设名称" min-width="160" />
            <ElTableColumn prop="maxRetries" label="最大重试次数" width="130" align="center">
              <template #default="{ row }">
                <span class="font-mono">{{ row.maxRetries ?? '-' }}</span>
              </template>
            </ElTableColumn>
            <ElTableColumn prop="backoffMs" label="退避毫秒" width="120" align="center">
              <template #default="{ row }">
                <span class="font-mono">{{ row.backoffMs ?? '-' }}</span>
              </template>
            </ElTableColumn>
            <template #empty>
              <ElEmpty description="暂无预设配置数据" />
            </template>
          </ElTable>
        </ElCard>
      </template>

      <!-- 详情弹窗 -->
      <ElDialog v-model="detailVisible" title="重试计划详情" width="560px">
        <div v-if="currentDetail" class="space-y-3">
          <div v-for="(value, key) in currentDetail" :key="String(key)" class="flex">
            <span class="w-28 shrink-0 text-gray-500">{{ String(key) }}：</span>
            <span class="break-all font-mono text-sm">{{ value ?? '-' }}</span>
          </div>
        </div>
      </ElDialog>
    </div>
  </Page>
</template>
